#!/usr/bin/env node
/**
 * build-worker-topo-bundle — K7 승격 S1 (260808).
 *
 * `src/lib/cad/workerTopoFacade.ts` → IIFE(`self.NexyTopo`) 번들:
 *   occt-worker/topo-naming.bundle.js  (+ public/occt-worker/ 사본)
 *
 * 클래식 워커는 TS/ESM 을 import 못 하므로 번들이 유일한 운반 수단이다.
 * 산출물은 커밋한다(occt-worker/ 의 다른 워커 파일과 같은 관례) — 재생성은
 * `npm run build:worker-topo`, 검증은 vitest 패리티 테스트가 한다.
 */
import { build } from 'esbuild';
import { copyFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outfile = join(root, 'occt-worker', 'topo-naming.bundle.js');

await build({
  entryPoints: [join(root, 'src', 'lib', 'cad', 'workerTopoFacade.ts')],
  bundle: true,
  format: 'iife',
  globalName: 'NexyTopo',
  target: 'es2020',
  outfile,
  alias: { '@': join(root, 'src') },
  banner: { js: '/* generated by scripts/build-worker-topo-bundle.mjs — do not edit (K7-S1) */' },
  logLevel: 'silent',
});

const pub = join(root, 'public', 'occt-worker');
mkdirSync(pub, { recursive: true });
copyFileSync(outfile, join(pub, 'topo-naming.bundle.js'));
console.log('[worker-topo] bundled → occt-worker/topo-naming.bundle.js (+public copy)');
